import { createGlobalStyle, css } from 'styled-components'
import interVariable from '~/assets/fonts/ordering/InterVariable.woff2'
import { variables } from '~/brand/ordering.tokens.generated'
import { ORDERING_BRAND_ALLOWLIST } from './allowlist'

/**
 * Ordering.co brand adapter for styled-components.
 *
 * The dashboard is a legacy styled-components surface, so it consumes the
 * released tokens as `--od-*` CSS variables instead of the shadcn/Tailwind
 * stack. Values come from the single token module
 * `src/brand/ordering.tokens.generated.js` (generated by
 * `node scripts/brand-system.mjs release-update`); `allowlist.js` only names
 * the subset a login-style surface scopes. Never hard-code values here.
 */

const pick = (names, pools, scope) => Object.fromEntries(names.map((name) => {
  const pool = pools.find((candidate) => candidate[name] !== undefined)
  if (!pool) throw new Error(`OrderingBrand: ${name} (${scope}) is not in src/brand/ordering.tokens.generated.js`)
  return [name, pool[name]]
}))

const { root, product, light, dark } = variables
const { root: rootNames, mode: modeNames } = ORDERING_BRAND_ALLOWLIST

export const ORDERING_BRAND = {
  root: pick(rootNames, [root, product], 'root'),
  light: pick(modeNames, [light, root, product], 'light'),
  dark: pick(modeNames, [dark, root, product], 'dark')
}

const declarations = (vars) => Object.entries(vars).map(([name, value]) => `${name}: ${value};`).join('\n')

/** Scope the brand variables on a container, light by default, dark with the OS setting. */
export const orderingBrandScope = css`
  ${declarations(ORDERING_BRAND.root)}
  ${declarations(ORDERING_BRAND.light)}
  color-scheme: light;

  @media (prefers-color-scheme: dark) {
    ${declarations(ORDERING_BRAND.dark)}
    color-scheme: dark;
  }
`

/** Self-hosted Inter, the face `--od-font-sans` names first. */
export const OrderingBrandFonts = createGlobalStyle`
  @font-face {
    font-family: 'Ordering Inter Local';
    src: url(${interVariable}) format('woff2');
    font-weight: 100 900;
    font-style: normal;
    font-display: swap;
  }
`

/** 2px action-blue ring with 2px offset, shown for keyboard focus only. */
export const orderingFocusRing = css`
  outline: 2px solid var(--od-focus);
  outline-offset: 2px;
`
